package main

// Offline file checks (contract 1.6, the "files" suite): "client keyring"
// reads an ETS keyring (.knxkeys) and reports what it holds, so the runner
// can compare implementations on the same file; "sim-keyring" writes the
// test profile as an ETS keyring generated by knx-sim, a second producer
// of the format next to scripts/secure-fixture.py.

import (
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/cB-Sigma/knx"
	"github.com/cB-Sigma/knx-sim/sim"
)

// keyring reports the keyring --file with --password: the tunnelling
// interfaces (address, user, password), the devices (address, management
// password, whether a tool key is exported), the backbone (key, latency)
// and the Data Secure group keys with their senders.
func keyring(a *args) (map[string]any, error) {
	if a.file == "" {
		return nil, errors.New("--file is required")
	}
	b, err := os.ReadFile(a.file)
	if err != nil {
		return nil, err
	}
	k, err := knx.ParseKeyring(b, a.password)
	if err != nil {
		return nil, err
	}
	interfaces := []map[string]any{}
	senders := map[string]map[string]bool{}
	for _, in := range k.Interfaces {
		if in.UserID != 0 {
			interfaces = append(interfaces, map[string]any{"address": in.IndividualAddress, "userId": in.UserID, "password": in.Password})
		}
		for g, ss := range in.Groups {
			if senders[g.String()] == nil {
				senders[g.String()] = map[string]bool{}
			}
			for _, s := range ss {
				senders[g.String()][s.String()] = true
			}
		}
	}
	sort.Slice(interfaces, func(i, j int) bool { return interfaces[i]["userId"].(int) < interfaces[j]["userId"].(int) })
	devices := []map[string]any{}
	for _, d := range k.Devices {
		devices = append(devices, map[string]any{"address": d.IndividualAddress, "managementPassword": d.ManagementPassword,
			"toolKey": len(d.ToolKey) == 16})
	}
	sort.Slice(devices, func(i, j int) bool { return devices[i]["address"].(string) < devices[j]["address"].(string) })
	groups := map[string]any{}
	for g, key := range k.DataSecureKeys {
		var ss []string
		for s := range senders[g.String()] {
			ss = append(ss, s)
		}
		sort.Strings(ss)
		groups[g.String()] = map[string]any{"key": strings.ToLower(hex.EncodeToString(key)), "senders": ss}
	}
	out := map[string]any{"interfaces": interfaces, "devices": devices, "groups": groups}
	if k.Backbone {
		out["backbone"] = map[string]any{"key": strings.ToLower(hex.EncodeToString(k.BackboneKey)),
			"latencyMs": k.BackboneLatency.Milliseconds()}
	}
	return out, nil
}

// runSimKeyring writes the test profile as a knx-sim ETS keyring to
// stdout: users 2 and 3, the host's device, the Data Secure groups with
// the profile's senders and the backbone key. knx-sim fixes the host's
// management password ("mgmt") and exports no tool keys.
func runSimKeyring() int {
	p, err := loadProfileJSON()
	if err != nil {
		fmt.Fprintln(os.Stderr, "profile:", err)
		return 1
	}
	var tunnels []sim.KeyringTunnel
	for _, id := range []string{"2", "3"} {
		u := p.Users[id]
		n := 2
		if id == "3" {
			n = 3
		}
		tunnels = append(tunnels, sim.KeyringTunnel{Address: u.Address, UserID: n, Password: u.Password})
	}
	groups := map[string][]byte{}
	for g, k := range p.DataSecureGroups {
		b, err := hex.DecodeString(k)
		if err != nil {
			fmt.Fprintln(os.Stderr, "profile: key of", g)
			return 1
		}
		groups[g] = b
	}
	backbone, err := hex.DecodeString(p.BackboneKey)
	if err != nil {
		fmt.Fprintln(os.Stderr, "profile: backbone key")
		return 1
	}
	os.Stdout.Write(sim.ETSKeyring(sim.KeyringOptions{Project: "knx-interop (knx-sim)", Password: p.KeyringPassword, Host: p.Host,
		DeviceAuth: p.DevicePassword, Tunnels: tunnels, SecureGroups: groups, Senders: p.Senders, BackboneKey: backbone}))
	return 0
}

// loadProfileJSON reads profile.json without the keyring.
func loadProfileJSON() (*profileJSON, error) {
	b, err := os.ReadFile(secureDir + "/profile.json")
	if err != nil {
		return nil, err
	}
	var p profileJSON
	return &p, json.Unmarshal(b, &p)
}

type profileJSON struct {
	profile
	BackboneKey      string            `json:"backboneKey"`
	DataSecureGroups map[string]string `json:"dataSecureGroups"`
}
